import {questions,topics,createSession,score,recordAnswer,blankStats,validSession} from './engine.js';
const app=document.querySelector('#app'), KEY='nj-road-ready-v1';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let stats=blankStats(), session=null, view='home', storageOK=true, offlineReady=false, deferredInstall=null, manual=null;
try{const old=JSON.parse(localStorage.getItem(KEY)||'null');if(old?.stats&&Array.isArray(old.stats.missed)&&Array.isArray(old.stats.seen)&&Array.isArray(old.stats.history)&&old.stats.topics){stats={...blankStats(),...old.stats};stats.missed=stats.missed.filter(id=>questions.some(q=>q.id===id));if(validSession(old.session))session=old.session;}}catch{storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify({stats,session}));}catch{storageOK=false;}}
function go(next){view=next;render();window.scrollTo({top:0,behavior:'instant'});app.querySelector('h1')?.focus({preventScroll:true});}
function nav(){return `<nav class="nav" aria-label="Main"><button data-view="home" class="${view==='home'?'active':''}">Practice</button><button data-view="progress" class="${view==='progress'?'active':''}">My progress</button><button data-view="guide" class="${view==='guide'?'active':''}">Study guide</button></nav>`;}
function home(){return `${nav()}<section class="intro"><p class="eyebrow">YOUR NEXT STOP: CONFIDENCE</p><h1 tabindex="-1">A little practice.<br>A safer driver.</h1><p>Learn the rules. Understand the why. Take it one question at a time.</p></section>${session&&!session.finished?`<div class="notice row">You have an unfinished ${session.mode==='exam'?'mock test':'practice session'}.<button class="secondary" data-action="resume">Continue question ${session.index+1}</button></div><br>`:''}<section class="launch"><div><span class="pill">10 QUESTIONS · INSTANT FEEDBACK</span><h2>Your daily drive</h2><p>A fresh mix of road rules, signs, and everyday driving decisions.</p><button class="primary" data-start="quick">Start quick practice →</button></div><div class="exam-mini"><p class="eyebrow">THE KNOWLEDGE TEST</p><strong>40<span> / 50</span></strong><p>Correct answers needed to pass.</p></div></section><section class="cards" aria-label="Practice modes"><article class="card"><p class="eyebrow">TEST YOURSELF</p><h3>Full mock test</h3><p>50 questions. Answers revealed at the end. Pass with 80%.</p><label class="source" for="duration">Practice timer</label><select id="duration" style="width:100%;margin:8px 0"><option value="0">No time limit</option><option value="30">30-minute challenge</option><option value="50">50-minute challenge</option></select><button class="secondary" data-start="exam">Take a mock test</button></article><article class="card"><p class="eyebrow">SPOT THE SIGNAL</p><h3>Signs & signals</h3><p>Recognize real signs from your manual and learn what to do next.</p><button class="secondary" data-start="topic" data-topic="Signs & signals">Practice road signs</button></article><article class="card"><p class="eyebrow">MAKE IT STICK</p><h3>Learn from mistakes</h3><p>${stats.missed.length?`${stats.missed.length} questions to revisit. Correct answers clear them from your list.`:'Missed questions collect here automatically. A fresh chance to get them right.'}</p><button class="secondary" data-start="mistakes" ${stats.missed.length?'':'disabled'}>Review mistakes${stats.missed.length?` (${stats.missed.length})`:''}</button></article></section><div class="section-head"><h2>Practice by topic</h2><span class="source">${questions.length} original questions</span></div><section class="topic-grid">${topics.map(t=>`<button class="topic" data-start="topic" data-topic="${esc(t)}"><div>${esc(t)}<span>${questions.filter(q=>q.topic===t).length} questions${stats.topics[t]?.answers?` · ${Math.round(stats.topics[t].correct/stats.topics[t].answers*100)}% accuracy`:''}</span></div><span aria-hidden="true">→</span></button>`).join('')}</section>${installHelp()}<p class="source">Mock test format: <a href="https://www.nj.gov/mvc/license/sample_knowledge_test.htm" target="_blank" rel="noopener">NJ MVC: 50 questions, 40 correct to pass</a>. Timed challenges are optional practice settings, not a claim about the official test’s time limit.</p>`;}
function installHelp(){return `<details class="notice install"><summary>Keep Road Ready on your phone</summary><p><strong>iPhone:</strong> Open this site in Safari, tap Share, then Add to Home Screen. <strong>Android:</strong> Open in Chrome, then use its menu → Install app or Add to Home screen.</p>${deferredInstall?'<button class="secondary" data-action="install">Install Road Ready</button>':''}<p id="offline-status">${offlineReady?'Offline practice is ready on this device.':navigator.onLine?'Preparing offline practice. Keep this page open briefly on your first visit.':'You are offline. Previously saved app content remains available.'}</p><p>Progress is kept separately on each device and browser. Clearing browser data removes it. Hosted sign-in may need a connection.</p></details>`;}
function progressView(){return `${nav()}<p class="eyebrow">YOUR LEARNING JOURNEY</p><h1 tabindex="-1">See how far you’ve come.</h1><div class="stats"><div class="stat"><strong>${stats.answers?Math.round(stats.correct/stats.answers*100)+'%':'—'}</strong><span>Answer accuracy</span></div><div class="stat"><strong>${stats.seen.length}/${questions.length}</strong><span>Questions explored</span></div><div class="stat"><strong>${stats.history.length}</strong><span>Sessions completed</span></div></div><div class="section-head"><h2>Topic confidence</h2></div><div class="topic-grid">${topics.map(t=>{const s=stats.topics[t];return `<div class="card"><h3>${esc(t)}</h3><p>${s?`${s.correct} of ${s.answers} attempts correct`:'Not practiced yet'}</p><progress class="progress" max="100" value="${s?Math.round(s.correct/s.answers*100):0}" aria-label="${esc(t)} accuracy"></progress><button class="secondary" data-start="topic" data-topic="${esc(t)}">Practice topic</button></div>`;}).join('')}</div><div class="section-head"><h2>Recent sessions</h2></div>${stats.history.length?stats.history.slice().reverse().slice(0,10).map(h=>`<div class="review-item row"><strong>${h.correct}/${h.total}</strong><span>${esc(h.label)} · ${new Date(h.date).toLocaleDateString()}${h.timedOut?' · Time ended':''}</span></div>`).join(''):'<p class="empty">Finish a practice session to see your results here.</p>'}<p class="source">Practice accuracy reflects your attempts, not a prediction of your official test score.</p>`;}
function guide(){const chapters=[['Licensing & GDL',4],['Driver testing',30],['Seat belts & car seats',40],['Vehicle control & parking',48],['Road rules & speed',62],['School buses & emergency vehicles',76],['Headlights & parking rules',83],['Defensive driving',90],['Alcohol & medication',114],['Sharing the road',144],['Signs & signals',212]];return `${nav()}<p class="eyebrow">YOUR 2026 MANUAL</p><h1 tabindex="-1">Understand the rule.</h1><p>Every question includes a printed-page reference. Read the source here, including offline after the app is saved.</p><div class="topic-grid">${chapters.map(([t,p])=>`<button class="topic" data-page="${p}"><div>${t}<span>Manual page ${p}</span></div><span aria-hidden="true">→</span></button>`).join('')}</div><p class="notice">These are original study questions for the basic automobile knowledge test. They do not reproduce the official exam and are not a complete substitute for reading the manual. This app uses the manual you supplied; it does not automatically update when laws change.</p><p><a href="https://www.nj.gov/mvc/pdf/license/drivermanual.pdf" target="_blank" rel="noopener">Open the official MVC PDF online</a></p>${installHelp()}`;}
function feedback(q,it){const good=it.selected===q.answer;return `<div class="feedback ${good?'':'wrong'}" role="status"><strong>${good?'Correct — nicely done.':'Not quite. Here’s the rule.'}</strong><p>${esc(q.explanation)}</p><button class="quiet source" data-page="${q.page}">Read manual page ${q.page}</button></div>`;}
function quiz(){if(!session)return home();if(session.finished)return results();const it=session.items[session.index],q=questions.find(q=>q.id===it.id),exam=session.mode==='exam';return `<section class="quiz"><div class="quiz-top"><button class="quiet" data-view="home">Save & exit</button><p>${exam?'Mock test':session.topic||'Practice'} · <span class="timer" id="timer">${timeText()}</span></p></div><progress class="progress" value="${session.index}" max="${session.items.length}" aria-label="Question progress"></progress><div class="question"><p class="eyebrow">QUESTION ${session.index+1} OF ${session.items.length} · ${esc(q.topic)}</p><h1 tabindex="-1">${esc(q.question)}</h1>${q.image?`<img class="sign" src="${q.image}" alt="Road sign to identify; see the visual symbol" width="190" height="180">`:''}<div class="answers" role="group" aria-label="Answer choices">${it.order.map((n,i)=>`<button class="answer ${it.selected===n?'selected':''} ${it.confirmed&&!exam?(n===q.answer?'correct':it.selected===n?'incorrect':''):''}" data-answer="${n}" aria-pressed="${it.selected===n}" ${it.confirmed?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(q.options[n])}</span>${it.confirmed&&!exam&&n===q.answer?'<span aria-label="Correct answer">✓</span>':''}</button>`).join('')}</div>${it.confirmed&&!exam?feedback(q,it):''}<div class="question-actions">${!it.confirmed?`<button class="primary" data-action="confirm" ${it.selected===null?'disabled':''}>${exam?'Save answer':'Check answer'}</button>`:`<button class="primary" data-action="next">${session.index===session.items.length-1?'See results':'Next question →'}</button>`}</div></div><p class="source">${exam?'Answers and explanations appear when the test ends.':'Select an answer, then check it to learn why.'} Your session saves automatically.</p></section>`;}
function results(){const s=score(session);return `<section class="quiz"><button class="quiet" data-view="home">← Back to practice</button><div class="intro"><p class="eyebrow">${session.timedOut?'TIME’S UP':'SESSION COMPLETE'}</p><h1 tabindex="-1">${s.passed?'A strong step forward.':'Keep building your confidence.'}</h1><div class="result-score">${s.correct}<span style="font-size:28px;color:var(--muted)"> / ${s.total}</span></div><p>${s.percent}% correct${session.mode==='exam'?` · ${s.passed?'Practice passing target reached':'Practice passing target: 40 of 50'}`:''}. ${session.timedOut?'Unanswered questions count as incorrect.':''}</p><div class="row"><button class="primary" data-start="quick">Try another 10</button><button class="secondary" data-start="mistakes" ${stats.missed.length?'':'disabled'}>Review mistakes (${stats.missed.length})</button></div></div><h2>Review your answers</h2>${session.items.map(it=>{const q=questions.find(q=>q.id===it.id),ok=it.confirmed&&it.selected===q.answer;return `<article class="review-item"><p class="eyebrow">${ok?'✓ CORRECT':'REVISIT'} · ${esc(q.topic)}</p>${q.image?`<img src="${q.image}" class="sign" alt="Road sign from this question" width="190" height="180">`:''}<h3>${esc(q.question)}</h3><p>Your answer: ${it.confirmed?esc(q.options[it.selected]):'Not answered'}<br><strong>Correct answer: ${esc(q.options[q.answer])}</strong></p><p>${esc(q.explanation)}</p><button class="quiet source" data-page="${q.page}">Read manual page ${q.page}</button></article>`;}).join('')}</section>`;}
function render(){app.innerHTML=(view==='quiz'?quiz():view==='progress'?progressView():view==='guide'?guide():home())+(!storageOK?'<p class="notice" role="status">Your browser is not allowing saved progress. You can still practice, but progress may disappear when you close this page.</p>':'');}
function start(mode,topic='',minutes=0){if(session&&!session.finished&&!window.confirm('Start a new session? This replaces your unfinished session; previously checked answers stay in your progress.'))return false;try{session=createSession(mode,topic,stats.missed,minutes);save();go('quiz');return true;}catch(e){window.alert(e.message);return false;}}
function confirm(){const it=session?.items[session.index];if(!it||it.confirmed||it.selected===null)return;it.confirmed=true;if(session.mode!=='exam')recordAnswer(stats,questions.find(q=>q.id===it.id),it.selected);save();render();}
function finish(timedOut=false){if(session.finished)return;session.finished=true;session.timedOut=timedOut;if(session.mode==='exam')for(const it of session.items){const q=questions.find(q=>q.id===it.id);if(it.confirmed)recordAnswer(stats,q,it.selected);else stats.missed=[...new Set([...stats.missed,q.id])];}const s=score(session);stats.history.push({...s,date:Date.now(),label:session.mode==='exam'?'Mock test':session.topic||'Mixed practice',timedOut});stats.history=stats.history.slice(-100);save();go('quiz');}
function timeText(){if(!session)return '';const sec=Math.max(0,Math.floor(((session.deadline??Date.now())-(session.deadline?Date.now():session.started))/1000));return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}${session.deadline?' left':' elapsed'}`;}
setInterval(()=>{if(session&&!session.finished){if(session.deadline&&Date.now()>=session.deadline){finish(true);return;}const el=document.querySelector('#timer');if(el)el.textContent=timeText();}},1000);
let sourceDialog=null;
async function showPage(page){if(!Number.isInteger(page)||page<1||page>241)return;sourceDialog?.remove();sourceDialog=document.createElement('dialog');sourceDialog.className='manual-dialog';document.body.append(sourceDialog);sourceDialog.innerHTML='<p>Loading manual…</p><button class="secondary" data-close>Close</button>';sourceDialog.showModal();sourceDialog.addEventListener('click',e=>{if(e.target.closest('[data-close]'))sourceDialog.close();const target=e.target.closest('[data-manual-page]');if(target)showPage(Number(target.dataset.manualPage));});try{manual??=await fetch('./manual-pages.json').then(r=>{if(!r.ok)throw Error('Manual unavailable');return r.json()});sourceDialog.innerHTML=`<div class="row"><h2>Manual page ${page}</h2><button class="secondary" data-close>Close</button></div><p class="source">2026 NJ Driver Manual · Text transcription; diagrams and layout are in the original PDF.</p><pre>${esc(manual[page]||'This page has no extractable text. Consult the original PDF for its diagrams.')}</pre><div class="row"><button class="quiet" data-manual-page="${page-1}" ${page===1?'disabled':''}>Previous page</button><button class="quiet" data-manual-page="${page+1}" ${page===241?'disabled':''}>Next page</button><a href="https://www.nj.gov/mvc/pdf/license/drivermanual.pdf#page=${page+2}" target="_blank" rel="noopener">Official PDF online</a></div>`;}catch{sourceDialog.innerHTML='<p>The manual text could not load. Reconnect and reopen this page to save it for offline use.</p><button class="secondary" data-close>Close</button>';}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view)go(b.dataset.view);else if(b.dataset.start)start(b.dataset.start,b.dataset.topic||'',Number(document.querySelector('#duration')?.value||0));else if(b.dataset.answer!==undefined&&session&&!session.finished){const it=session.items[session.index];if(!it.confirmed){it.selected=Number(b.dataset.answer);save();render();}}else if(b.dataset.page)showPage(Number(b.dataset.page));else if(b.dataset.action==='resume')go('quiz');else if(b.dataset.action==='confirm')confirm();else if(b.dataset.action==='next'&&session?.items[session.index].confirmed){if(session.index<session.items.length-1){session.index++;save();go('quiz');}else finish();}else if(b.dataset.action==='install'&&deferredInstall){await deferredInstall.prompt();deferredInstall=null;render();}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();go('home')});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;if(view!=='quiz')render();});
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(async reg=>{const channel=new MessageChannel();channel.port1.onmessage=e=>{offlineReady=e.data?.ready===true;const el=document.querySelector('#offline-status');if(el)el.textContent=offlineReady?'Offline practice is ready on this device.':'Offline saving is still in progress.';};reg.active?.postMessage('status',[channel.port2]);}).catch(()=>{const el=document.querySelector('#offline-status');if(el)el.textContent='Offline installation is unavailable in this browser. You can still practice online.';});}
const mc=document.modelContext;if(mc?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'get_practice_progress',description:'Read device-local NJ driver practice progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({answers:stats.answers,correct:stats.correct,missed:stats.missed.length,completed:stats.history.length})},{name:'start_quick_practice',description:'Start a ten-question practice session if no unfinished session exists.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||Object.keys(input).length)throw Error('Expected an empty object');if(session&&!session.finished)throw Error('An unfinished session already exists');start('quick');return {started:true,questions:session.items.length};}}]){try{Promise.resolve(mc.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
render();
